class Solution {
    private static final int MOD=1_000_000_007;
    private String text;
    private boolean prime(char digit){
        return digit=='2'||digit=='3'||digit=='5'||digit=='7';
    }
    private boolean boundary(int position){
        return position==0||position==text.length()||!prime(text.charAt(position-1))&&prime(text.charAt(position));
    }
    public int beautifulPartitions(String s,int k,int minLength){
        text=s;
        int n=s.length();
        if(!prime(s.charAt(0))||prime(s.charAt(n-1)))return 0;
        long[] dp=new long[n+1];
        dp[0]=1;
        for(int part=0;part<k;part++){
            long[] next=new long[n+1];
            long running=0;
            for(int end=1;end<=n;end++){
                int start=end-minLength;
                if(start>=0&&boundary(start))running=(running+dp[start])%MOD;
                if(boundary(end))next[end]=running;
            }
            dp=next;
        }
        return (int)dp[n];
    }
}

