        };
        var dp=LongArray(n+1);
        dp[0]=1;
        repeat(k){
            val next=LongArray(n+1);
            var running=0L;
            for(end in 1..n){
                val start=end-minLength;
                if(start>=0&&boundary(start))running=(running+dp[start])%mod;
                if(boundary(end))next[end]=running
